export const errorCatalogueSource = "{\n  \"schemaVersion\": 1,\n  \"helpPath\": \"/help/\",\n  \"entries\": [\n    {\"code\": \"session_ended\", \"for\": \"owner\", \"title\": \"The session ended\", \"cause\": \"The sign-in is no longer valid on this server. The policies and drafts are saved.\", \"next\": \"Sign in with your wallet again.\"},\n    {\"code\": \"sign_in_expired\", \"for\": \"owner\", \"title\": \"The sign-in message expired\", \"cause\": \"Each sign-in message works once and for a short time. This one was used, changed or too old.\", \"next\": \"Start the sign-in again and approve the new message in your wallet.\"},\n    {\"code\": \"sign_in_signature_invalid\", \"for\": \"owner\", \"title\": \"The wallet signature did not match\", \"cause\": \"The signature that the wallet returned does not belong to the account and the message of this sign-in.\", \"next\": \"Select the account that you want to use in your wallet, then sign in again.\"},\n    {\"code\": \"app_origin_required\", \"for\": \"agent\", \"title\": \"The request did not come from the Allowit app\", \"cause\": \"This server takes owner requests only from the pages of its own app. A page of another address, or an allowit CLI of another release, sent this one.\", \"next\": \"Open Allowit at the address of this server's app, sign in there and do the step again.\", \"agent\": \"Install the allowit CLI again with the install line of this server's app. Then run the command again.\"},\n    {\"code\": \"rate_limited\", \"for\": \"owner\", \"title\": \"Too many requests at once\", \"cause\": \"Allowit limits how often this step runs. Nothing was lost.\", \"next\": \"Wait a minute, then do the step again.\"},\n    {\"code\": \"service_not_configured\", \"for\": \"operator\", \"title\": \"This server does not offer this function\", \"cause\": \"The server has no configuration for the function that this step needs.\", \"next\": \"Use another network or another Allowit server. The operator of this server can turn the function on.\"},\n    {\"code\": \"storage_unavailable\", \"for\": \"owner\", \"title\": \"The change was not saved\", \"cause\": \"The server could not write to its storage. Nothing changed.\", \"next\": \"Do the step again in a moment.\"},\n    {\"code\": \"service_unreachable\", \"for\": \"owner\", \"title\": \"Allowit did not answer\", \"cause\": \"The Allowit server could not be reached, or its answer was unreadable. The step may have reached the server before the connection failed.\", \"next\": \"Check your connection and reload the page. Read the policy's state before you do the step again.\", \"agent\": \"Check ALLOWIT_URL and the connection. Then run the same command again with the same request ID, so that a request that reached the server is not done twice.\"},\n    {\"code\": \"server_release_differs\", \"for\": \"agent\", \"title\": \"The CLI and the server are different releases\", \"cause\": \"The server does not know the request of this allowit CLI. The server is an earlier or a later release than the CLI, or ALLOWIT_URL names another site.\", \"next\": \"Give the agent the agent prompt from Agent access again: its install line installs the CLI that this server serves.\", \"agent\": \"Check ALLOWIT_URL. Then install the CLI that this server serves: run the install line of its app again, and run the command again.\"},\n    {\"code\": \"method_not_allowed\", \"for\": \"agent\", \"title\": \"The server does not take this request here\", \"cause\": \"The route exists and takes another kind of request. A CLI of another release than the server sends such a request.\", \"next\": \"Give the agent the agent prompt from Agent access again: its install line installs the CLI that this server serves.\", \"agent\": \"Check ALLOWIT_URL. Then install the CLI that this server serves: run the install line of its app again, and run the command again.\"},\n\n    {\"code\": \"wallet_unavailable\", \"for\": \"owner\", \"title\": \"The wallet did not connect\", \"cause\": \"The app found no wallet extension that it can use, or the wallet refused the connection.\", \"next\": \"Install or unlock your wallet extension, allow this site, and choose the network that the app shows. Then sign in again.\"},\n    {\"code\": \"wallet_signing_failed\", \"for\": \"owner\", \"title\": \"The wallet did not sign\", \"cause\": \"The wallet returned an error in place of a signature. Nothing was sent.\", \"next\": \"Open your wallet, check that the owner account and the network are selected, and sign the step again.\"},\n    {\"code\": \"signing_cancelled\", \"for\": \"owner\", \"title\": \"The signature was cancelled\", \"cause\": \"The wallet closed without a signature. Nothing was sent and nothing changed.\", \"next\": \"Start the step again when you want to sign.\"},\n    {\"code\": \"wallet_wrong_account\", \"for\": \"owner\", \"title\": \"The signature does not fit the owner account\", \"cause\": \"The wallet returned a signature that does not verify for the owner account and this step: another account signed, or the wallet signed an earlier message. Nothing was saved or sent.\", \"next\": \"Select the owner account in your wallet and sign this step again.\"},\n    {\"code\": \"owner_wrong_network\", \"for\": \"owner\", \"title\": \"The owner account is on another network\", \"cause\": \"The sign-in is on another network than the one that this policy uses.\", \"next\": \"Choose the policy's network in the header, sign in with your owner account there, and open Review and sign again.\"},\n    {\"code\": \"owner_account_unfunded\", \"for\": \"owner\", \"title\": \"The owner account has no funds yet\", \"cause\": \"The network holds no account for the owner address. An account exists from the moment it receives its first funds.\", \"next\": \"Send funds to your owner address. On a test network, use the faucet of that network. Then open Review and sign again.\"},\n    {\"code\": \"owner_balance_low\", \"for\": \"owner\", \"title\": \"The owner account holds too little\", \"cause\": \"The owner account pays the funding amount of the wallet and the reserve that the network keeps. It holds less than both together.\", \"next\": \"Add funds to your owner account, or state a lower funding amount in the conversation. Then sign again.\"},\n    {\"code\": \"account_not_found\", \"for\": \"owner\", \"title\": \"The network holds no account for this address\", \"cause\": \"An account exists from the moment it receives its first funds. The owner account has none on this network, or the wallet account of this policy was closed.\", \"next\": \"Check in your wallet that your owner account holds funds on this network. If it does, the wallet was closed: start a new policy.\"},\n    {\"code\": \"owner_step_open\", \"for\": \"owner\", \"title\": \"Another step waits for the owner's signature\", \"cause\": \"One owner step runs at a time for an account, in this tab and in every other tab.\", \"next\": \"Finish or cancel the open step, then start this one.\"},\n    {\"code\": \"signer_unavailable\", \"for\": \"owner\", \"title\": \"The app cannot sign on this network\", \"cause\": \"The app holds no wallet connection that signs owner steps on this network.\", \"next\": \"Choose a network from the header's list and sign in there.\"},\n\n    {\"code\": \"model_busy\", \"for\": \"owner\", \"title\": \"The drafting model is busy\", \"cause\": \"Nothing was lost. No model wrote the draft this time, and the words stay in the form.\", \"next\": \"Choose Try again. Allowit sends the same request and creates at most one draft.\"},\n    {\"code\": \"model_timeout\", \"for\": \"owner\", \"title\": \"The model took too long\", \"cause\": \"The model did not answer within its time limit. Nothing was saved.\", \"next\": \"Send the same request again.\"},\n    {\"code\": \"model_unreachable\", \"for\": \"owner\", \"title\": \"The model could not be reached\", \"cause\": \"Allowit could not connect to the model that this step uses. Nothing was saved.\", \"next\": \"Send the same request again in a moment.\"},\n    {\"code\": \"build_gate_unavailable\", \"for\": \"owner\", \"title\": \"The policy check did not run\", \"cause\": \"Allowit builds each draft to check it. That check was unavailable, so no draft changed.\", \"next\": \"Send the same request again in a moment.\"},\n    {\"code\": \"build_gate\", \"for\": \"owner\", \"title\": \"The draft did not pass the policy check\", \"cause\": \"Allowit wrote a policy from the request several times, and its check refused each one. Nothing was saved.\", \"next\": \"Say what the agent may do in plain terms: the amounts, the recipients and a time limit. Then send it again.\"},\n    {\"code\": \"recognizer_mismatch\", \"for\": \"operator\", \"title\": \"Allowit could not classify the draft\", \"cause\": \"Two checks of the policy source disagree. This is a fault of the server, not of the policy.\", \"next\": \"Send the request again. If it repeats, give the operator of this server the code recognizer_mismatch.\"},\n    {\"code\": \"wallet_kind_unknown\", \"for\": \"owner\", \"title\": \"Choose a wallet kind\", \"cause\": \"The step names no wallet kind, or a kind that Allowit does not know.\", \"next\": \"Choose Native, Simple, Standard or Custom in the wallet kind list. Then do the step again.\"},\n    {\"code\": \"wallet_kind_unsupported\", \"for\": \"owner\", \"title\": \"This wallet kind cannot serve the policy\", \"cause\": \"The chosen wallet kind cannot enforce this policy on this network. The details state the reason.\", \"next\": \"Read the reason in the details, then choose a wallet kind in the list that can enforce this policy on this network.\"},\n    {\"code\": \"custom_policy_needs_custom_wallet\", \"for\": \"owner\", \"title\": \"This policy needs a Custom wallet\", \"cause\": \"The policy holds custom conditions that only a Custom wallet compiles.\", \"next\": \"Choose the Custom wallet kind and send the request again.\"},\n    {\"code\": \"server_policy_needs_server_custody\", \"for\": \"owner\", \"title\": \"A Custom wallet cannot hold this policy\", \"cause\": \"A part of the policy looks something up or asks a question, which only the server can run. This server deploys a Custom wallet only for a policy that it compiles whole on chain.\", \"next\": \"Choose the Standard wallet kind, whose contract checks the canonical rules on chain, or Native, whose rules the server checks before it co-signs. Either kind runs the lookup on the server.\"},\n    {\"code\": \"host_value_needs_source\", \"for\": \"owner\", \"title\": \"The wallet cannot store one of the values\", \"cause\": \"The part of the policy that the server runs reads a value that a contract wallet does not keep.\", \"next\": \"Choose the Native wallet kind, or state that value as a fixed number in your request.\"},\n    {\"code\": \"agent_public_key_invalid\", \"for\": \"owner\", \"title\": \"The agent public key is not valid here\", \"cause\": \"The key in the message is not an account address on this network, or the wallet already serves another agent key.\", \"next\": \"Copy the public key that the agent printed, whole, and send it again. If the wallet already serves another key, use that key, or set up a new wallet for the new key.\"},\n    {\"code\": \"funding_amount_invalid\", \"for\": \"owner\", \"title\": \"The funding amount is not a plain number\", \"cause\": \"Allowit reads the funding amount as a positive decimal number, such as 10 or 2.5.\", \"next\": \"State the amount again in the conversation as a plain number.\"},\n    {\"code\": \"wallet_creation_prepared\", \"for\": \"owner\", \"title\": \"This draft is fixed\", \"cause\": \"A wallet creation was prepared for this draft, so its values can no longer change.\", \"next\": \"Sign it in Review and sign, or start a new policy for other values.\"},\n    {\"code\": \"time_passed\", \"for\": \"owner\", \"title\": \"The time limit is in the past\", \"cause\": \"The policy ends at a time that has already passed.\", \"next\": \"State a new time limit in the conversation, or change the Expires value in the policy code.\"},\n    {\"code\": \"asset_mismatch\", \"for\": \"owner\", \"title\": \"The request names another asset\", \"cause\": \"The policy counts in one asset and the request or its wallet uses another.\", \"next\": \"Name the asset of the policy's wallet, or start a new policy for the other asset.\"},\n    {\"code\": \"param_invalid\", \"for\": \"owner\", \"title\": \"A value has the wrong form\", \"cause\": \"One of the values is not what its rule expects, such as text where a number belongs.\", \"next\": \"Open the value in the policy code and enter it again in the form that its editor shows.\"},\n    {\"code\": \"param_out_of_range\", \"for\": \"owner\", \"title\": \"A value is out of range\", \"cause\": \"One of the values is smaller or larger than its rule allows.\", \"next\": \"Open the value in the policy code and enter a value inside the range in the details.\"},\n    {\"code\": \"workspace_full\", \"for\": \"owner\", \"title\": \"The workspace is full\", \"cause\": \"An account keeps up to 30 policies.\", \"next\": \"Stop a policy that you no longer use. A stopped policy frees its place. Then create the new one.\"},\n    {\"code\": \"prompt_length\", \"for\": \"owner\", \"title\": \"The request is too short or too long\", \"cause\": \"Allowit drafts a policy from a request of 5 to 3,000 characters.\", \"next\": \"Say what the agent may do in a few sentences and send it again.\"},\n    {\"code\": \"conversation_full\", \"for\": \"owner\", \"title\": \"This conversation is full\", \"cause\": \"A draft keeps a limited number of revisions.\", \"next\": \"Start a new policy and state the complete rules in its first message.\"},\n    {\"code\": \"policy_not_found\", \"for\": \"owner\", \"title\": \"This policy is not in the workspace\", \"cause\": \"The signed-in account has no policy with this id. It was removed, or it belongs to another account or network.\", \"next\": \"Open the policy list, check the network and the account in the header, and choose the policy again.\"},\n    {\"code\": \"policy_revision_changed\", \"for\": \"owner\", \"title\": \"The draft changed in the meantime\", \"cause\": \"The change was made for an earlier revision of this draft. Another tab or request saved a newer one.\", \"next\": \"Reload the page, read the current revision, and make the change again.\"},\n    {\"code\": \"draft_signed\", \"for\": \"owner\", \"title\": \"A signed policy is not revised\", \"cause\": \"This policy is signed and its wallet exists. Its source no longer changes.\", \"next\": \"Change a value in the policy code with one signature, or start a new policy for other rules.\"},\n    {\"code\": \"review_values_missing\", \"for\": \"owner\", \"title\": \"The agent key or the funding amount is missing\", \"cause\": \"Review and sign needs the public key of the agent and the amount that funds the wallet. The conversation has not collected both.\", \"next\": \"Give your agent the agent setup line. Then state its public key and the funding amount in the conversation.\"},\n    {\"code\": \"agent_key_is_owner\", \"for\": \"owner\", \"title\": \"The agent key is not a key of its own\", \"cause\": \"The agent public key equals the owner account or the key of the server. The agent must hold a key of its own.\", \"next\": \"Give your agent the agent setup line, and state the public key that it prints in the conversation.\"},\n    {\"code\": \"draft_changed\", \"for\": \"owner\", \"title\": \"The draft changed after it was opened\", \"cause\": \"Review and sign shows one exact revision, and the saved draft is at another one now. Nothing was signed.\", \"next\": \"Close the review, read the current revision, and open Review and sign again.\"},\n    {\"code\": \"review_busy\", \"for\": \"owner\", \"title\": \"This review is being signed elsewhere\", \"cause\": \"The same review runs in this tab or in another tab of this browser.\", \"next\": \"Finish it there, or close the other tab and open Review and sign again.\"},\n    {\"code\": \"review_link_invalid\", \"for\": \"owner\", \"title\": \"The review link is incomplete\", \"cause\": \"The link from the chat does not hold a complete policy proposal.\", \"next\": \"Return to the chat and open its Review and sign link again.\"},\n    {\"code\": \"review_differs\", \"for\": \"owner\", \"title\": \"The saved policy differs from the reviewed one\", \"cause\": \"The server's draft is not the source, the values or the wallet kind that this review shows. Nothing was signed.\", \"next\": \"Close the review, open the policy from the list, and review it again.\"},\n\n    {\"code\": \"draft_running\", \"for\": \"owner\", \"title\": \"Allowit is still busy with a draft\", \"cause\": \"A conversation writes one draft at a time, and new drafts are limited to a few each minute. The last draft is unchanged.\", \"next\": \"Wait a minute, then send your message again.\"},\n    {\"code\": \"agent_capacity\", \"for\": \"owner\", \"title\": \"The agent takes no more conversations now\", \"cause\": \"This agent keeps a limited number of open conversations and drafts.\", \"next\": \"Try again in a few minutes.\"},\n    {\"code\": \"conversation_ended\", \"for\": \"owner\", \"title\": \"This conversation ended\", \"cause\": \"The agent no longer holds this conversation. A policy that was opened in Allowit is saved there.\", \"next\": \"Start a new conversation and say again what the agent may do.\"},\n\n    {\"code\": \"wallet_not_set_up\", \"for\": \"owner\", \"title\": \"The agent's wallet account does not exist yet\", \"cause\": \"A Native policy pays from a new account that the owner's signature creates for the agent. This draft names an account that was never set up.\", \"next\": \"Start the policy from New policy with the Native kind. Review and sign then creates and funds the account with one signature.\"},\n    {\"code\": \"wallet_setup_required\", \"for\": \"owner\", \"title\": \"Set up the wallet account first\", \"cause\": \"The policy's wallet is a new account for the agent. It exists once the owner signs its setup.\", \"next\": \"Open Review and sign and choose Sign and fund. The first signature creates and funds the account.\"},\n    {\"code\": \"wallet_not_deployed\", \"for\": \"owner\", \"title\": \"The wallet is not deployed yet\", \"cause\": \"The policy has no wallet on the network, so it cannot be approved or run.\", \"next\": \"Open Review and sign and finish the deployment.\"},\n    {\"code\": \"draft_not_bindable\", \"for\": \"owner\", \"title\": \"This wallet account cannot hold the draft\", \"cause\": \"The account that was set up does not match the draft. The details state what differs.\", \"next\": \"Start a new policy and sign its setup again.\"},\n    {\"code\": \"wallet_already_registered\", \"for\": \"owner\", \"title\": \"This wallet belongs to another policy\", \"cause\": \"The wallet account is registered with another owner or another agent key.\", \"next\": \"Start a new policy. Review and sign creates a new wallet account for it.\"},\n    {\"code\": \"installation_unverified\", \"for\": \"owner\", \"title\": \"The wallet exists, and Allowit has not confirmed it yet\", \"cause\": \"The network confirmed the creation of the wallet. Allowit then read the wallet from the ledger, and that read failed or showed other values.\", \"next\": \"Choose Resume in Review and sign. It reads the wallet again and signs nothing twice.\"},\n    {\"code\": \"template_changed\", \"for\": \"owner\", \"title\": \"The network's wallet settings changed\", \"cause\": \"The asset or the fee ceiling of this network's wallets changed after this draft was made.\", \"next\": \"Start a new policy with the same words. The new draft uses the current settings.\"},\n    {\"code\": \"owner_transaction_expired\", \"for\": \"owner\", \"title\": \"The signature came too late\", \"cause\": \"A prepared step is valid for a few minutes. This one expired before the network took it, so it never applied.\", \"next\": \"Choose Resume. Allowit prepares a new step for you to sign.\"},\n    {\"code\": \"owner_transaction_pending\", \"for\": \"owner\", \"title\": \"The network has not confirmed the step yet\", \"cause\": \"The signed step was sent, and its result is not known yet.\", \"next\": \"Wait a moment and choose Resume. Do not sign again: the saved step is sent again as it is.\"},\n    {\"code\": \"owner_transaction_settled\", \"for\": \"owner\", \"title\": \"An earlier step already settled\", \"cause\": \"A step that the owner signed before this one is on the ledger. Allowit reads its result before it prepares a new step.\", \"next\": \"Choose Resume, or open History to see the settled step.\"},\n    {\"code\": \"owner_transaction_failed\", \"for\": \"owner\", \"title\": \"The network refused the step\", \"cause\": \"The transaction that the owner signed reached the network and failed there. The most frequent cause is an owner account that holds too little for the amount, the reserve and the fee.\", \"next\": \"Check the balance of your owner account and add funds if it is low. Then choose Resume to sign a new step.\"},\n    {\"code\": \"owner_result_unavailable\", \"for\": \"owner\", \"title\": \"The result of an earlier step is no longer readable\", \"cause\": \"The step settled some time ago, and the network's recent history no longer holds its result.\", \"next\": \"Open History and the wallet's explorer link to see what applied. Then continue from the policy page.\"},\n    {\"code\": \"stale_owner_observation\", \"for\": \"owner\", \"title\": \"The wallet changed while the step was prepared\", \"cause\": \"Allowit read the wallet, and the ledger changed it before the step was ready.\", \"next\": \"Do the step again. Allowit reads the current state.\"},\n    {\"code\": \"network_unavailable\", \"for\": \"owner\", \"title\": \"The network did not answer\", \"cause\": \"Allowit got no answer in time from the payment network or the server. When the details say to retry with the same request ID, nothing was sent; otherwise the step may have reached the network.\", \"next\": \"Wait a moment and reload the page. If the step shows as pending, choose Resume. Start it again only when the page shows that it did not apply.\", \"agent\": \"Run the same command again with the same request ID, so that a request that reached the network is not done twice.\"},\n    {\"code\": \"operation_expired\", \"for\": \"agent\", \"title\": \"The prepared payment expired\", \"cause\": \"A prepared operation is valid for a short time. This one was not submitted in time, and nothing was paid.\", \"next\": \"No action is needed. The agent prepares the payment again.\", \"agent\": \"Prepare the payment again with a new request ID.\"},\n    {\"code\": \"params_differ_from_wallet\", \"for\": \"owner\", \"title\": \"The wallet enforces other values\", \"cause\": \"The values that the policy shows differ from the values that its wallet holds on the ledger.\", \"next\": \"Open the policy and compare its values with History. Change a value with one signature, or deploy a new wallet for other values.\"},\n    {\"code\": \"rail_journal_unreadable\", \"for\": \"operator\", \"title\": \"The server's wallet journal is unreadable\", \"cause\": \"The journal of this wallet on the server uses a retired format.\", \"next\": \"The operator keeps the current data directory, which holds the record of earlier operations, and resolves this wallet's pending operations before the server uses a new data directory.\"},\n    {\"code\": \"custom_policy_unknown\", \"for\": \"owner\", \"title\": \"No Custom policy waits for this build\", \"cause\": \"The server holds no Custom policy with this id and build ticket.\", \"next\": \"Copy the build command from Review and sign again and run it.\"},\n    {\"code\": \"custom_code_hash_mismatch\", \"for\": \"owner\", \"title\": \"The built code differs\", \"cause\": \"The wallet code on the server or on the ledger is not the code that this client built from the policy source, or a deployed wallet runs other code than its record names.\", \"next\": \"Do not sign. Before a deployment, run the build command from Review and sign again and sign only when the hashes match. For a deployed wallet, stop using it and tell the operator.\"},\n    {\"code\": \"custom_toolchain_missing\", \"for\": \"owner\", \"title\": \"A build tool is missing\", \"cause\": \"The build of a Custom wallet needs build tools on this machine. The details name the tool that is missing or has another version.\", \"next\": \"Install the tool that the details name, then run the build command again.\"},\n    {\"code\": \"custom_build_failed\", \"for\": \"owner\", \"title\": \"The wallet code did not build\", \"cause\": \"The build tools ran and the build of the policy source failed. The details hold the compiler's output.\", \"next\": \"Revise the policy in the conversation so that it builds, then run the new build command.\"},\n    {\"code\": \"custom_build_missing\", \"for\": \"owner\", \"title\": \"This Custom policy has no build yet\", \"cause\": \"A Custom wallet runs code that is built from the policy source. The server has received no build for this policy.\", \"next\": \"Copy the build command from Review and sign and run it in a terminal with the allowit CLI.\"},\n    {\"code\": \"custom_policy_changed\", \"for\": \"owner\", \"title\": \"The policy changed during the build\", \"cause\": \"The source of the policy is not the source that the build command named.\", \"next\": \"Copy the build command from Review and sign again and build that source.\"},\n    {\"code\": \"custom_build_attested\", \"for\": \"owner\", \"title\": \"The build is already attested\", \"cause\": \"The owner attested a build of this policy, and an attested build does not change.\", \"next\": \"Deploy that build, or revise the policy and build it again.\"},\n    {\"code\": \"custom_presignature_mismatch\", \"for\": \"owner\", \"title\": \"The attestation belongs to another build\", \"cause\": \"The attestation names another build ticket than the one of this policy's source.\", \"next\": \"Run the build command again and sign the attestation of that build.\"},\n    {\"code\": \"custom_attestation_invalid\", \"for\": \"owner\", \"title\": \"The build attestation is not valid\", \"cause\": \"The signature of the attestation is not the owner account's signature for this build.\", \"next\": \"Run the build command again and sign the attestation with your owner account.\"},\n\n    {\"code\": \"update_unavailable\", \"for\": \"owner\", \"title\": \"This policy takes no signed value change\", \"cause\": \"Only an active policy changes a value with a signature, and only for the values that its wallet stores.\", \"next\": \"Change a draft's value directly in its policy code. For a stopped policy, choose Resume first. A value that the active wallet does not store cannot change in place: create a new policy with the new value.\"},\n    {\"code\": \"revision_changed\", \"for\": \"owner\", \"title\": \"The values changed in the meantime\", \"cause\": \"The policy's values are at a newer revision than the one that this change was made for.\", \"next\": \"Reload the page, read the current values, and make the change again.\"},\n    {\"code\": \"update_unrecorded\", \"for\": \"owner\", \"title\": \"The change is on the ledger and not yet saved\", \"cause\": \"The network confirmed the change. The server did not save the new value in its record.\", \"next\": \"Enter the same value again. Allowit finds the confirmed change and saves it without a second signature.\"},\n    {\"code\": \"nothing_to_return\", \"for\": \"owner\", \"title\": \"Nothing of this asset can return\", \"cause\": \"The wallet holds nothing of the chosen asset above what it must keep, so none of it can move back to the owner.\", \"next\": \"Check the asset that the return names. The wallet's balance shows whether another asset, such as its fee balance, can still return.\"},\n    {\"code\": \"wallet_closed\", \"for\": \"owner\", \"title\": \"This wallet is closed\", \"cause\": \"The wallet account no longer exists on the network. Its funds returned to the owner when it closed.\", \"next\": \"Start a new policy for a new wallet.\"},\n    {\"code\": \"policy_build_identity_changed\", \"for\": \"owner\", \"title\": \"The policy needs the owner's approval again\", \"cause\": \"Allowit updated the release that runs the server part of this policy. The owner's approval covered the earlier release.\", \"next\": \"Open the policy in the Allowit app and approve it again.\", \"agent\": \"Tell the owner that the policy needs approval again in the Allowit app. Then send the request again with a new request ID.\"},\n\n    {\"code\": \"policy_unknown\", \"for\": \"agent\", \"title\": \"The server has no policy with this id\", \"cause\": \"The policy id in the command is not a policy of this server. The line was cut, or it belongs to another server.\", \"next\": \"Copy the agent prompt from Agent access on the policy page and give your agent the whole line.\", \"agent\": \"Ask the owner for the agent prompt from the Allowit app again. Check ALLOWIT_URL.\"},\n    {\"code\": \"not_policy_agent\", \"for\": \"agent\", \"title\": \"This key is not the agent key of the policy\", \"cause\": \"The request is signed with another key than the agent public key that the owner gave the policy.\", \"next\": \"Check the agent public key under Agent access. The agent must sign with that key, or the agent's key needs a new policy.\", \"agent\": \"Sign with the key whose public key you gave the owner: allowit keys use NAME. Or give the owner this public key for a new policy.\"},\n    {\"code\": \"policy_denied\", \"for\": \"agent\", \"title\": \"The policy denied the payment\", \"cause\": \"The request breaks the policy, such as an amount limit, a recipient list or a time limit. The details name the rule when the wallet reports one. Nothing was paid.\", \"next\": \"Open History on the policy page. It shows the request and why it was denied. Change a value in the policy code only when the details name a limit that the agent needs to pass.\", \"agent\": \"Do not retry the same request. Read the limits with allowit POLICY_ID help. Tell the owner what was denied, with the rule when the details name one.\"},\n    {\"code\": \"server_policy_denied\", \"for\": \"agent\", \"title\": \"The policy's server part refused the request\", \"cause\": \"The part of the policy that the server runs stopped at one of its limits or could not complete a required lookup. Nothing was paid.\", \"next\": \"Open History on the policy page: it shows the request and the reason.\", \"agent\": \"Tell the owner. The owner sees the request and its reason in History.\"},\n    {\"code\": \"decision_denied\", \"for\": \"agent\", \"title\": \"The policy's question denied the request\", \"cause\": \"The policy asks a question about each request, and the answer for this one was below the owner's threshold. Nothing was paid.\", \"next\": \"Open History on the policy page to read the reason. If the answer was wrong, change the thresholds in the policy code when they are values of the policy, or start a new policy.\", \"agent\": \"Tell the owner. The owner reads the reason in History and can change the policy.\"},\n    {\"code\": \"operation_changed\", \"for\": \"agent\", \"title\": \"The operation changed while it was read\", \"cause\": \"Another request changed this operation at the same moment.\", \"next\": \"No action is needed. The agent reads the operation's state again.\", \"agent\": \"Read its status again with the same request ID.\"},\n    {\"code\": \"operation_unresolved\", \"for\": \"agent\", \"title\": \"The server could not read the operation now\", \"cause\": \"The read changed nothing, and the request ID stays valid.\", \"next\": \"No action is needed. The agent reads the operation's state again.\", \"agent\": \"Read the status again with the same request ID.\"},\n    {\"code\": \"operation_refused\", \"for\": \"agent\", \"title\": \"The server refused the operation\", \"cause\": \"The server did not prepare or submit this operation. The details state the reason. Nothing was paid.\", \"next\": \"Open History to see the refused request. The details name what to correct.\", \"agent\": \"Correct what the details name, then send the request with a new request ID.\"},\n    {\"code\": \"request_id_binds_other_input\", \"for\": \"agent\", \"title\": \"This request ID belongs to another request\", \"cause\": \"The request ID was used before with a different amount, recipient or operation.\", \"next\": \"No action is needed. The agent sends the request with a new request ID.\", \"agent\": \"Send this request with a new request ID. Keep one request ID for each intended payment.\"},\n    {\"code\": \"paid_service_mismatch\", \"for\": \"agent\", \"title\": \"The payment and the service call differ\", \"cause\": \"The seller's terms name another recipient, asset or amount than the payment in this request.\", \"next\": \"No action is needed. The agent pays exactly what the seller's terms name.\", \"agent\": \"Read the seller's terms again with allowit call. Pay only when they match what was agreed; if the recipient, the asset or the amount changed, ask the owner first.\"},\n    {\"code\": \"challenge_already_paid\", \"for\": \"agent\", \"title\": \"This service call is already paid\", \"cause\": \"Another request of this policy pays the same call of the seller.\", \"next\": \"No action is needed. History shows the payment that settled.\", \"agent\": \"Read the status of that request with its request ID. Do not pay again.\"},\n    {\"code\": \"wallet_paused\", \"for\": \"agent\", \"title\": \"The owner stopped this policy\", \"cause\": \"The wallet is paused, so the agent cannot pay from it.\", \"next\": \"Open the policy in the Allowit app and choose Resume.\", \"agent\": \"Stop paying. Tell the owner that the policy is stopped.\"},\n    {\"code\": \"insufficient_funds\", \"for\": \"agent\", \"title\": \"The wallet holds too little\", \"cause\": \"The wallet does not hold what the operation needs, such as the payment amount and its network fee, or the vault shares of a redemption.\", \"next\": \"Check what the operation needs in the details. Send the wallet that asset, or ask for a smaller amount. The policy page shows the wallet's address under Funding.\", \"agent\": \"Tell the owner what the wallet lacks, as the details say. Then send the request again with a new request ID, for the same or a smaller amount.\"},\n    {\"code\": \"stale_request\", \"for\": \"agent\", \"title\": \"The request is out of date\", \"cause\": \"The wallet moved past the state that this request or step was prepared for: another payment or owner step changed it first.\", \"next\": \"Reload the policy page and prepare the step again.\", \"agent\": \"Send the payment again as a new request with a new request ID.\"},\n    {\"code\": \"wallet_rejected\", \"for\": \"agent\", \"title\": \"A contract refused the operation\", \"cause\": \"The wallet, its asset or a vault refused the operation in simulation. The details name the contract error when it is known. Nothing was paid.\", \"next\": \"Open the policy page and check that the wallet is active. The details name the contract error.\", \"agent\": \"Read the contract error in the details. Run allowit POLICY_ID help to check the wallet's state, and tell the owner if the wallet is stopped or changed.\"},\n    {\"code\": \"seller_failed\", \"for\": \"agent\", \"title\": \"The seller did not complete the call\", \"cause\": \"The seller refused, failed, or sent no usable payment terms. This is not a denial of the policy.\", \"next\": \"No action is needed. A payment that settled is not repeated, and History shows it.\", \"agent\": \"Check allowit status first. If the payment is pending or settled, stop and do not pay another seller. Only when nothing was paid, try again later or choose another seller.\"},\n    {\"code\": \"policy_not_active\", \"for\": \"agent\", \"title\": \"The policy is not active\", \"cause\": \"The owner stopped or changed the policy. Nothing was signed.\", \"next\": \"Open the policy in the Allowit app. Choose Resume, or finish Review and sign.\", \"agent\": \"Run allowit POLICY_ID help to read its state, and ask the owner.\"},\n    {\"code\": \"wallet_unverified\", \"for\": \"agent\", \"title\": \"The ledger does not show this wallet for the policy\", \"cause\": \"The wallet that this device imported does not hold the policy on the network now. Nothing was signed.\", \"next\": \"Check on the policy page that the wallet is active on this network, and tell the agent if it changed.\", \"agent\": \"Check the network endpoint with allowit rail show. Then ask the owner whether the wallet still exists, and import it again.\"},\n    {\"code\": \"wallet_differs\", \"for\": \"agent\", \"title\": \"The policy now pays from another wallet\", \"cause\": \"The owner deployed the policy to another wallet than the one that this device imported. Nothing was signed.\", \"next\": \"No action is needed. The agent imports the current wallet of the policy.\", \"agent\": \"Run allowit wallet import --policy=POLICY_ID, then allowit wallet use with the new wallet.\"},\n    {\"code\": \"server_key_differs\", \"for\": \"agent\", \"title\": \"The server key differs from the trusted one\", \"cause\": \"The server names another key for this policy than the key that this device pinned. Nothing was signed or imported.\", \"next\": \"Compare the key with Server public key under Agent access in the Allowit app. If they differ, stop.\", \"agent\": \"Stop. Ask the owner which server key the app shows under Agent access.\"},\n    {\"code\": \"request_proof_refused\", \"for\": \"agent\", \"title\": \"The server refused the request's signature\", \"cause\": \"The request is signed with the agent key, and the server could not verify it. A wrong device clock is the usual cause.\", \"next\": \"No action is needed. The agent sets its device's clock and sends the request again.\", \"agent\": \"Set this device's clock, then run the command again.\"},\n\n    {\"code\": \"credits_exhausted\", \"for\": \"owner\", \"title\": \"The credits do not cover a request\", \"cause\": \"Allowit charges the policy's owner credits for each request that it evaluates, and the owner's available credits are less than one request costs. Allowit refused this request before it evaluated the policy: nothing was signed, sent or charged.\", \"next\": \"Open Credits in the header and get credits. Your policies, funds and History still work without them.\", \"agent\": \"Tell the owner to get credits from Allowit: the app shows the balance and how. You need no credits of your own. Then run the same command again with the same request ID.\"},\n    {\"code\": \"credits_insufficient\", \"for\": \"owner\", \"title\": \"The credits do not cover a lookup of the policy\", \"cause\": \"The policy looks something up or asks a model before it decides. The owner's credits cover the request and not that call, so the request was denied.\", \"next\": \"Open Credits in the header and get credits.\", \"agent\": \"Tell the owner to get credits from Allowit. Then send the request again with a new request ID. Do not work around the denial.\"},\n    {\"code\": \"allowance_exhausted\", \"for\": \"owner\", \"title\": \"Today's analysis allowance is used up\", \"cause\": \"The owner limits how many search and model calls a policy makes each day, and what they cost. This request needed one more, so it was denied.\", \"next\": \"Open Usage on the policy page and raise the allowance, or wait until 00:00 UTC.\", \"agent\": \"Tell the owner to raise the analysis allowance of the policy in the app, or wait until 00:00 UTC. Then send the request again with a new request ID.\"},\n    {\"code\": \"credits_unavailable\", \"for\": \"agent\", \"title\": \"Allowit released no decision\", \"cause\": \"The server could not reserve or save the charge of this request, so it decided nothing. Nothing was signed or sent.\", \"next\": \"No action is needed. The agent sends the same request again.\", \"agent\": \"Run the same command again with the same request ID.\"},\n    {\"code\": \"evaluation_conflict\", \"for\": \"agent\", \"title\": \"This request ID already has a decision\", \"cause\": \"An earlier evaluation of the same request ID decided first. The ledger keeps that decision.\", \"next\": \"No action is needed. History shows how Allowit decided the request.\", \"agent\": \"Read it with allowit status ID. For a new payment, use a new request ID.\"},\n    {\"code\": \"evaluation_running\", \"for\": \"agent\", \"title\": \"Allowit is evaluating this request now\", \"cause\": \"An earlier call with the same request ID has not ended.\", \"next\": \"No action is needed. Allowit is deciding the request now.\", \"agent\": \"Read the request with allowit status ID --wait 60s, with the same request ID.\"},\n    {\"code\": \"call_unpriced\", \"for\": \"operator\", \"title\": \"The policy made a call without a price\", \"cause\": \"The policy asked for a lookup that the price list of this server does not price, so the call was not made.\", \"next\": \"The operator of this server adds a price for the call. Until then, remove that lookup from the policy.\"},\n    {\"code\": \"charge_unknown\", \"for\": \"owner\", \"title\": \"No charge exists for this request\", \"cause\": \"Allowit charges a request when it evaluates it. This request was never evaluated.\", \"next\": \"Check the request ID in History.\"},\n    {\"code\": \"grant_id_used\", \"for\": \"operator\", \"title\": \"This grant id was used before\", \"cause\": \"The grant id already granted credits to this owner.\", \"next\": \"Use a new id for another grant.\"},\n    {\"code\": \"operator_credential_required\", \"for\": \"operator\", \"title\": \"Only the operator grants credits\", \"cause\": \"The request carries no operator credential. An owner session does not grant credits.\", \"next\": \"Send the operator credential as a bearer token.\"},\n\n    {\"code\": \"owner_review_pending\", \"for\": \"agent\", \"title\": \"The request waits for its owner\", \"cause\": \"The policy holds this request until the owner allows or denies it. Nothing was paid.\", \"next\": \"Open Approval on the policy page and choose Allow or Deny.\", \"agent\": \"Ask the owner to answer the request in the Allowit app. Then send the same request again with the same request ID.\"},\n    {\"code\": \"owner_review_allowed\", \"for\": \"agent\", \"title\": \"The owner allowed the request\", \"cause\": \"The request is released and has no payment yet.\", \"next\": \"No action is needed. The agent sends the allowed request before the time in the details.\", \"agent\": \"Send the same request again with the same request ID before the time in the details.\"},\n    {\"code\": \"owner_review_denied\", \"for\": \"agent\", \"title\": \"The request was denied\", \"cause\": \"The owner, or the policy's question after new evidence, denied this request. Nothing was paid.\", \"next\": \"No action is needed. The agent asks before it tries another payment of this kind.\", \"agent\": \"Do not send it again. Ask the owner before you try another payment of this kind.\"},\n    {\"code\": \"owner_review_expired\", \"for\": \"agent\", \"title\": \"The request expired\", \"cause\": \"The owner did not answer in time, or an allowed request was not sent in time. It counts as denied.\", \"next\": \"Answer the new request in Approval when the agent sends it.\", \"agent\": \"Send a new request with a new request ID, and tell the owner that it waits.\"},\n    {\"code\": \"owner_review_request_changed\", \"for\": \"agent\", \"title\": \"This request ID waits with other values\", \"cause\": \"The request ID is held for the owner with a different amount, recipient or text.\", \"next\": \"No action is needed. The agent sends the request as it was answered, or a new one.\", \"agent\": \"Send the original request unchanged, or use a new request ID for the new one.\"},\n    {\"code\": \"owner_review_spent\", \"for\": \"agent\", \"title\": \"This approval is already used\", \"cause\": \"The owner's approval of this request was already used for an operation. That operation may still be pending, or it may have failed.\", \"next\": \"Open History to see the operation of the allowed request.\", \"agent\": \"Read the operation with allowit status ID before you start another payment. For another payment, send a new request.\"},\n    {\"code\": \"owner_review_second_question\", \"for\": \"agent\", \"title\": \"The request needs the owner again\", \"cause\": \"The owner allowed the request at one point of the policy, and it stopped at another point that also needs the owner. One request carries one answer, so the request is denied.\", \"next\": \"Change the policy so that it asks you once for this kind of request: revise a draft in the conversation, or start a new policy.\", \"agent\": \"Do not send it again: a new request stops at the same point. Tell the owner that the policy asks twice for this request.\"},\n    {\"code\": \"owner_review_unknown\", \"for\": \"owner\", \"title\": \"This request is not in the owner's list\", \"cause\": \"No waiting request with this id belongs to the signed-in account.\", \"next\": \"Open the policy and choose a request from Approval.\"},\n    {\"code\": \"owner_review_snapshot_stale\", \"for\": \"owner\", \"title\": \"The evidence was fetched again\", \"cause\": \"The request shows newer evidence than the page that was answered.\", \"next\": \"Read the request again in Approval and answer what it shows now.\"},\n    {\"code\": \"owner_review_snapshot_mismatch\", \"for\": \"owner\", \"title\": \"The answer does not match the request\", \"cause\": \"The answer names evidence that this request never had.\", \"next\": \"Open the request again in Approval and answer what it shows.\"},\n    {\"code\": \"owner_review_answered\", \"for\": \"owner\", \"title\": \"This request is already decided\", \"cause\": \"The owner, the policy's question or the time limit decided the request before this answer.\", \"next\": \"Read the request again in Approval to see how it ended.\"},\n    {\"code\": \"owner_review_signature_invalid\", \"for\": \"owner\", \"title\": \"The answer is not signed by the owner account\", \"cause\": \"The wallet signed with another account, or signed another message than this answer.\", \"next\": \"Select the policy's owner account in your wallet and choose Allow or Deny again.\"},\n    {\"code\": \"owner_review_not_owner\", \"for\": \"owner\", \"title\": \"These requests belong to another owner\", \"cause\": \"The signed-in account does not own this policy.\", \"next\": \"Sign in with the owner account of the policy.\"},\n    {\"code\": \"owner_review_refetch_unavailable\", \"for\": \"owner\", \"title\": \"The evidence cannot be fetched again\", \"cause\": \"This server cannot repeat the lookups of the request.\", \"next\": \"Answer the request as it is, or let it expire.\"},\n    {\"code\": \"owner_review_refetch_limit\", \"for\": \"owner\", \"title\": \"The evidence was fetched too often\", \"cause\": \"A request takes a limited number of refetches, a few seconds apart.\", \"next\": \"Wait a few seconds. After the last refetch, answer the request as it is.\"},\n    {\"code\": \"owner_review_changed\", \"for\": \"owner\", \"title\": \"The request changed during the answer\", \"cause\": \"New evidence, an answer or a reopening changed the request at the same moment.\", \"next\": \"Read the request again in Approval.\"},\n    {\"code\": \"owner_review_not_reopenable\", \"for\": \"owner\", \"title\": \"This decision cannot be reopened\", \"cause\": \"Only a denied or expired request that paid nothing is reopened, and only a decision that the policy's question scored is flagged.\", \"next\": \"Read the decision and its operation in History. Reopen applies to a denied or expired request that paid nothing, and Deny next time to a past decision that the policy's question scored. A waiting request can always be denied.\"},\n    {\"code\": \"owner_review_policy_changed\", \"for\": \"owner\", \"title\": \"The policy changed since this decision\", \"cause\": \"The request was decided under an earlier version of the policy.\", \"next\": \"Ask the agent to send a new request under the current policy.\", \"agent\": \"Send a new request with a new request ID. The current policy decides it.\"},\n    {\"code\": \"owner_review_answer_superseded\", \"for\": \"owner\", \"title\": \"A later answer stands\", \"cause\": \"The owner answered this request again after the decision that was opened.\", \"next\": \"Open the latest decision of the request to flag it.\"},\n    {\"code\": \"owner_review_explanation_unavailable\", \"for\": \"owner\", \"title\": \"No explanation is available now\", \"cause\": \"Allowit could not write the short explanation of the score.\", \"next\": \"Decide from the evidence on the page: it is everything that the decision saw.\"},\n    {\"code\": \"owner_review_invalid\", \"for\": \"owner\", \"title\": \"The request cannot be held or answered\", \"cause\": \"The answer is malformed, or the policy already has too many requests that wait for the owner.\", \"next\": \"Reload the page and answer again. If many requests wait in Approval, answer some of them first.\"},\n    {\"code\": \"owner_review_refetch_undecided\", \"for\": \"owner\", \"title\": \"The request cannot be evaluated again\", \"cause\": \"The server cannot run this request once more. The details state why.\", \"next\": \"Answer the request as it is.\"},\n\n    {\"code\": \"decision_review_needed\", \"for\": \"agent\", \"title\": \"The owner must decide this request\", \"cause\": \"The answer to the policy's question fell between the owner's thresholds.\", \"next\": \"Open Approval on the policy page and answer the request.\", \"agent\": \"Ask the owner to answer the request in the Allowit app.\"},\n    {\"code\": \"decision_unavailable\", \"for\": \"agent\", \"title\": \"The policy's question got no answer\", \"cause\": \"The model that answers the policy's question did not answer, so the request was not allowed. Nothing was paid.\", \"next\": \"No action is needed. The agent sends the request again in a moment.\", \"agent\": \"Send the request again with a new request ID in a moment.\"},\n    {\"code\": \"decision_unconfigured\", \"for\": \"operator\", \"title\": \"This server answers no policy questions\", \"cause\": \"The policy asks a question about each request, and this server has no model for it.\", \"next\": \"Use a server that answers questions, or remove the question from the policy.\"},\n    {\"code\": \"decision_blocked\", \"for\": \"owner\", \"title\": \"The model refused to read the request\", \"cause\": \"The content filter of the model blocked the text of the request or its evidence.\", \"next\": \"Open History to read the request. Allow such requests by a fixed rule, or ask the agent to send plain text.\"},\n    {\"code\": \"decision_evidence_too_large\", \"for\": \"owner\", \"title\": \"The request is too large for the question\", \"cause\": \"The request and what the policy looked up exceed what the model reads at once.\", \"next\": \"Ask the agent to send a shorter request text. To shorten the policy's lookups, revise a draft in the conversation, or start a new policy for a signed one.\"},\n    {\"code\": \"decision_past_answers_unavailable\", \"for\": \"agent\", \"title\": \"The owner's earlier answers could not be read\", \"cause\": \"The policy's question reads the owner's past answers, and the server could not load them.\", \"next\": \"No action is needed. The agent sends the request again in a moment.\", \"agent\": \"Send the request again with a new request ID in a moment.\"},\n    {\"code\": \"decision_thresholds_invalid\", \"for\": \"owner\", \"title\": \"The thresholds of the question are invalid\", \"cause\": \"The score below which the policy denies is higher than the score above which it allows, or a threshold is out of range.\", \"next\": \"Open the policy code. Set both thresholds from 0 to 10,000, with the deny threshold below the allow threshold.\"},\n    {\"code\": \"decision_question_invalid\", \"for\": \"owner\", \"title\": \"The policy's question is invalid\", \"cause\": \"The question is empty, too long or malformed.\", \"next\": \"In a draft, state the question again in the conversation in one or two plain sentences. A signed policy keeps its source: start a new policy.\"},\n    {\"code\": \"fetch_request_refused\", \"for\": \"owner\", \"title\": \"The policy's lookup is not allowed\", \"cause\": \"The lookup is malformed or exceeds a fixed bound of a fetch.\", \"next\": \"In a draft, state the lookup's address again in the conversation as a plain https URL. A signed policy keeps its source: start a new policy with the corrected lookup.\"},\n    {\"code\": \"fetch_address_refused\", \"for\": \"owner\", \"title\": \"The lookup address is not public\", \"cause\": \"The policy reads a URL that does not resolve to public internet addresses only.\", \"next\": \"Use a public https address for the lookup.\"},\n    {\"code\": \"fetch_unauthorized\", \"for\": \"owner\", \"title\": \"The looked-up service refused access\", \"cause\": \"The service that the policy reads answered that the request is not authorized.\", \"next\": \"Check the access to that service. To change the lookup, revise a draft in the conversation, or start a new policy for a signed one.\"},\n    {\"code\": \"fetch_failed\", \"for\": \"agent\", \"title\": \"The policy's lookup failed\", \"cause\": \"The service that the policy reads did not answer with usable content, so the request was not allowed.\", \"next\": \"No action is needed. If it repeats, check that the service that the policy reads is up.\", \"agent\": \"Send the request again with a new request ID in a moment.\"},\n    {\"code\": \"fetch_signature_invalid\", \"for\": \"owner\", \"title\": \"The lookup's signature is not valid\", \"cause\": \"The policy expects a signed answer from the service, and the answer carries no signature of the expected key.\", \"next\": \"Check the service's signing key. To change the key or the lookup, revise a draft in the conversation, or start a new policy for a signed one.\"},\n    {\"code\": \"fetch_tls_key_refused\", \"for\": \"owner\", \"title\": \"The service's certificate key changed\", \"cause\": \"The policy pins the key of the service that it reads, and the service presents another key.\", \"next\": \"Confirm the new key with the service. Then state it in a draft's conversation, or start a new policy for a signed one.\"},\n    {\"code\": \"internet_search_unconfigured\", \"for\": \"operator\", \"title\": \"This server runs no web search\", \"cause\": \"The policy searches the web, and this server has no search provider.\", \"next\": \"Use a server with search, or remove the search from the policy.\"},\n    {\"code\": \"internet_search_failed\", \"for\": \"agent\", \"title\": \"The policy's web search failed\", \"cause\": \"The search did not answer, so the request was not allowed. Nothing was paid.\", \"next\": \"No action is needed. The agent sends the request again in a moment.\", \"agent\": \"Send the request again with a new request ID in a moment.\"},\n    {\"code\": \"internet_search_no_results\", \"for\": \"agent\", \"title\": \"The policy's web search found nothing\", \"cause\": \"The search ran and found no source for this request, so the policy did not allow it.\", \"next\": \"Open History to see the request. A recipient or a service that the web does not know may need a fixed rule in a new policy.\", \"agent\": \"Tell the owner. A recipient or a service that the web does not know may need a fixed rule.\"},\n    {\"code\": \"internet_search_query_invalid\", \"for\": \"owner\", \"title\": \"The policy's search query is invalid\", \"cause\": \"The query that the policy builds is empty, too long or malformed.\", \"next\": \"In a draft, state again in the conversation what the policy searches for. A signed policy keeps its source: start a new policy.\"},\n    {\"code\": \"request_screening_malformed\", \"for\": \"owner\", \"title\": \"The policy's request check is malformed\", \"cause\": \"The custom code of the policy hands the server data in a form that it does not read.\", \"next\": \"In a draft, revise the policy in the conversation so that it builds its check again. A signed policy keeps its source: start a new policy.\"},\n    {\"code\": \"price_denied\", \"for\": \"agent\", \"title\": \"The price is outside the policy's range\", \"cause\": \"The policy compares the price of this payment with a market or vault price, and the price failed that check. Nothing was paid.\", \"next\": \"Open History to see the price that the policy refused.\", \"agent\": \"Send a request at a price inside the policy's range, or tell the owner which price the policy refused.\"},\n    {\"code\": \"price_unavailable\", \"for\": \"agent\", \"title\": \"The price could not be read\", \"cause\": \"The server could not observe the price that the policy checks, so the request was not allowed.\", \"next\": \"No action is needed. The agent sends the request again in a moment.\", \"agent\": \"Send the request again with a new request ID in a moment.\"},\n    {\"code\": \"evidence_call_limit\", \"for\": \"owner\", \"title\": \"The policy made too many lookups\", \"cause\": \"One evaluation admits a limited number of lookups, and the policy asked for more.\", \"next\": \"In a draft, revise the policy in the conversation so that it uses fewer lookups for each request. A signed policy keeps its source: start a new policy.\"},\n    {\"code\": \"evidence_snapshot_mismatch\", \"for\": \"operator\", \"title\": \"The stored evidence does not match\", \"cause\": \"A repeated evaluation made other lookups than the stored evidence holds.\", \"next\": \"Send a new request with a new request ID. If it repeats, give the operator the code evidence_snapshot_mismatch.\"},\n    {\"code\": \"marketplace_search_unavailable\", \"for\": \"agent\", \"title\": \"The catalog did not answer the policy\", \"cause\": \"The policy searches the service catalog, and the catalog was unavailable.\", \"next\": \"No action is needed. The agent sends the request again in a moment.\", \"agent\": \"Send the request again with a new request ID in a moment.\"},\n    {\"code\": \"marketplace_search_no_results\", \"for\": \"agent\", \"title\": \"The catalog has no such service\", \"cause\": \"The policy searched the service catalog for this request and found no entry on this network.\", \"next\": \"No action is needed. The agent chooses a seller from the catalog, or asks you.\", \"agent\": \"Choose a seller from allowit skills search, or tell the owner.\"},\n    {\"code\": \"marketplace_search_query_invalid\", \"for\": \"owner\", \"title\": \"The policy's catalog query is invalid\", \"cause\": \"The query that the policy builds is empty, too long or malformed.\", \"next\": \"In a draft, state again in the conversation what the policy searches the catalog for. A signed policy keeps its source: start a new policy.\"},\n\n    {\"code\": \"marketplace_unavailable\", \"for\": \"agent\", \"title\": \"This server has no service catalog\", \"cause\": \"The catalog of paid services is not configured on this server.\", \"next\": \"No action is needed. The agent pays a seller directly with its address.\", \"agent\": \"Pay a seller directly with allowit call and its URL, or use a server with a catalog.\"},\n    {\"code\": \"marketplace_cursor_stale\", \"for\": \"agent\", \"title\": \"The search results changed\", \"cause\": \"The catalog or its ranking changed since the first page of results.\", \"next\": \"No action is needed. The agent searches the catalog again.\", \"agent\": \"Search again without a cursor.\"},\n    {\"code\": \"marketplace_entry_not_found\", \"for\": \"agent\", \"title\": \"The catalog has no entry with this id\", \"cause\": \"The entry was removed, or the id is cut.\", \"next\": \"No action is needed. The agent searches the catalog again.\", \"agent\": \"Search again with allowit skills search and use an id from the results.\"},\n    {\"code\": \"facilitator_rate_limited\", \"for\": \"agent\", \"title\": \"The facilitator is at its request limit\", \"cause\": \"The Allowit facilitator serves a limited number of requests each minute.\", \"next\": \"No action is needed. The agent tries the call again in a minute.\", \"agent\": \"Try the call again in a minute.\"},\n    {\"code\": \"facilitator_fee_budget_exhausted\", \"for\": \"operator\", \"title\": \"The facilitator's fee budget is used up\", \"cause\": \"The facilitator pays the network fee of each settlement from a budget for each hour, and that budget is spent.\", \"next\": \"Try the call again in the next hour. The operator can raise the budget.\"},\n    {\"code\": \"authorization_already_settled\", \"for\": \"agent\", \"title\": \"This payment is already settled\", \"cause\": \"The facilitator settled this payment authorization before.\", \"next\": \"No action is needed. History shows the settled payment.\", \"agent\": \"Read the payment with allowit status ID. Do not pay again.\"},\n    {\"code\": \"authorization_in_settlement\", \"for\": \"agent\", \"title\": \"This payment is being settled now\", \"cause\": \"Another request settles the same payment authorization at this moment.\", \"next\": \"No action is needed. History shows the payment when it settles.\", \"agent\": \"Read the payment with allowit status ID in a moment.\"},\n    {\"code\": \"facilitator_busy\", \"for\": \"agent\", \"title\": \"The facilitator had no free turn\", \"cause\": \"The settlement got no turn in time. Nothing was sent.\", \"next\": \"No action is needed. The agent tries the call again.\", \"agent\": \"Run the same call again. It sends the same authorization, which settles at most once: it is no second payment.\"}\n  ]\n}\n";
export const errorCatalogue = freeze(JSON.parse(errorCatalogueSource));
const errorEntries = new Map(errorCatalogue.entries.map(entry => [entry.code, entry]));
export function errorEntry(code) { return typeof code === 'string' ? errorEntries.get(code) ?? null : null; }
export function errorHelpPath(code) { return typeof code === 'string' && /^[a-z][a-z0-9_]{2,63}$/.test(code) ? errorCatalogue.helpPath + code : errorCatalogue.helpPath.slice(0, -1); }
